export interface Spell {
  id: string;
  name: string;
  level: number;
  class: string;
  range: string;
  duration: string;
  areaOfEffect: string;
  components: string;
  castingTime: string;
  savingThrow: string;
  phbPage: number;
  description: string;
}

export const spells: Spell[] = [
  { id: "mu-1-burning-hands", name: "Burning Hands", level: 1, class: "Magic User", range: "0", duration: "1 round", areaOfEffect: "Special", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 64, description: "When the magic-user casts this spell, a jet of searing flame shoots from the fingertips. The hands must be held with thumbs touching and fingers spread. The flames shoot 3 feet in front of the magic-user. Any creature in the area takes 1 hit point of damage per level of the caster. Flammable materials will ignite." },
  { id: "mu-1-charm-person", name: "Charm Person", level: 1, class: "Magic User", range: "12\"", duration: "Special", areaOfEffect: "One person", components: "V, S", castingTime: "1", savingThrow: "Neg.", phbPage: 64, description: "Except as noted above, this spell affects any single person the magic-user selects. The term person includes any bipedal human, demi-human or humanoid of man-size or smaller, such as brownies, dryads, dwarves, elves, gnolls, gnomes, goblins, half-elves, halflings, half-orcs, hobgoblins, humans, kobolds, lizard men, nixies, orcs, pixies, sprites, troglodytes, and so on. The creature must be in range and alive. The charm spell will make the charmed creature react as a close friend and ally." },
  { id: "mu-1-comprehend-languages", name: "Comprehend Languages", level: 1, class: "Magic User", range: "Touch", duration: "5 rounds/level", areaOfEffect: "One written object or speaking creature", components: "V, S, M", castingTime: "1 round", savingThrow: "None", phbPage: 64, description: "When this spell is cast, the magic-user is able to understand the spoken words of a creature or read an otherwise incomprehensible written message. In either case, the magic-user must touch the creature or the writing. The material components are a pinch of soot and a few grains of salt." },
  { id: "mu-1-dancing-lights", name: "Dancing Lights", level: 1, class: "Magic User", range: "4\" + 1\"/level", duration: "2 rounds/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 65, description: "When dancing lights is cast, the magic-user creates, at his or her option, 1 to 4 lights which resemble either torches or lanterns, glowing spheres of light, or one faintly glowing, vaguely man-like shape. The lights move as the magic-user desires, forward or back, straight or turning, without concentration required, remaining within range. The material component is a bit of phosphorus or wychwood, or a glowworm." },
  { id: "mu-1-detect-magic", name: "Detect Magic", level: 1, class: "Magic User", range: "0", duration: "2 rounds/level", areaOfEffect: "1\" path, 6\" long", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 65, description: "When the detect magic spell is cast, the magic-user detects magical radiations in a path 1\" wide and up to 6\" long, in the direction he or she is facing. The intensity of the magic can be determined (dim, faint, moderate, strong, overwhelming), and the magic-user has a 10% chance per level of determining the type of magic (alteration, conjuration, etc.) if it is not his or her own." },
  { id: "mu-1-enlarge", name: "Enlarge", level: 1, class: "Magic User", range: "5\"/level", duration: "1 turn/level", areaOfEffect: "One creature or object", components: "V, S, M", castingTime: "1", savingThrow: "Neg.", phbPage: 65, description: "This spell causes instant growth of a creature or object, increasing both size and weight. It can be cast only upon a single creature or a single object. The creature or object can be increased in size anywhere from 10% to 10% per level of experience of the magic-user. The material component is a pinch of powdered iron." },
  { id: "mu-1-erase", name: "Erase", level: 1, class: "Magic User", range: "3\"", duration: "Permanent", areaOfEffect: "One scroll or 2 pages of writing", components: "V, S", castingTime: "1", savingThrow: "Special", phbPage: 65, description: "The erase spell removes writings of either magical or mundane nature from a scroll or from one or two pages of paper, parchment, or similar surfaces. It removes explosive runes, glyphs of warding, and wizard marks as well as normal writing. The chance for successfully erasing magical writings is 90% minus 5% per level of the writer." },
  { id: "mu-1-feather-fall", name: "Feather Fall", level: 1, class: "Magic User", range: "1\"/level", duration: "1 segment/level", areaOfEffect: "Special", components: "V", castingTime: "1 segment", savingThrow: "None", phbPage: 66, description: "When this spell is cast, the creature(s) or object(s) affected immediately assumes the mass of a feathery piece of down. The rate of falling is thus instantly changed to a mere 2 feet per second (120 feet per round), and no damage is incurred upon landing while the spell is in effect. The spell can be cast upon the magic-user or some other creature or object up to the maximum range of 1\" per level of the magic-user." },
  { id: "mu-1-find-familiar", name: "Find Familiar", level: 1, class: "Magic User", range: "1 mile/level", duration: "Special", areaOfEffect: "One creature", components: "V, S, M", castingTime: "2d12 hours", savingThrow: "Special", phbPage: 66, description: "This spell enables the magic-user to attempt to summon a familiar to act as his or her aid and companion. Familiars are typically small creatures such as cats, frogs, crows, hawks, snakes, owls, or weasels. The magic-user calls for a familiar, and one creature within range answers if conditions permit. The familiar grants the magic-user special powers depending on its nature." },
  { id: "mu-1-friends", name: "Friends", level: 1, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "6\" radius", components: "V, S, M", castingTime: "1", savingThrow: "Neg.", phbPage: 66, description: "A friends spell temporarily causes the magic-user to gain 2d4 points of charisma. Naturally, this spell works best when cast before a potential reaction check. The material components for this spell are chalk (or white flour), lampblack (or soot), and vermilion applied to the face before casting the spell." },
  { id: "mu-1-hold-portal", name: "Hold Portal", level: 1, class: "Magic User", range: "2\"/level", duration: "1 round/level", areaOfEffect: "20 sq. ft./level", components: "V", castingTime: "1", savingThrow: "None", phbPage: 66, description: "This spell magically holds shut a door, gate, window, or shutter of wood, metal, or stone. The magic-user may hold shut any such construction as if it were held shut by a lock. The hold portal has the effect of a delayed door close if it is cast upon something which is not yet in contact (such as a rising portcullis). The reverse of this spell, open portal, operates in the same manner to open held portals." },
  { id: "mu-1-identify", name: "Identify", level: 1, class: "Magic User", range: "0", duration: "1 segment/level", areaOfEffect: "One object", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 67, description: "When an identify spell is cast, one item may be touched and handled by the magic-user so as to give him or her a chance of determining what the item is. The base chance is 15%, plus 5% per level of the caster. The material components of this spell are a pearl (of at least 100 gp value) and an owl feather steeped in wine, with the infusion drunk and a live miniature crab consumed." },
  { id: "mu-1-jump", name: "Jump", level: 1, class: "Magic User", range: "Touch", duration: "1d3 rounds + 1 round/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 67, description: "The individual touched when this spell is cast is empowered to leap once per round as follows: forward 30 feet, backward 9 feet, straight up 15 feet. The jump spell has no effect on encumbrance. The material component is a grasshopper's hind leg, consumed in the casting." },
  { id: "mu-1-light", name: "Light", level: 1, class: "Magic User", range: "6\"", duration: "1 turn/level", areaOfEffect: "2\" radius globe", components: "V, M", castingTime: "1", savingThrow: "None", phbPage: 67, description: "This spell creates a luminous glow, equal to torchlight, within a fixed radius of the spell's center point. Objects in darkness beyond this sphere can be seen, at best, as vague and indistinct shapes. The spell is centered on a point selected by the magic-user. The material component is a firefly or a piece of phosphorescent moss." },
  { id: "mu-1-magic-missile", name: "Magic Missile", level: 1, class: "Magic User", range: "6\" + 1\"/level", duration: "Special", areaOfEffect: "One or more creatures", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 67, description: "Use of the magic missile spell creates one or more missiles of magical energy that dart forth from the magic-user's fingertip and unerringly strike their target. Each missile does 2-5 (d4+1) hit points of damage. For every 2 levels of experience of the magic-user, a missile is added: 2 at 3rd-4th, 3 at 5th-6th, 4 at 7th-8th, 5 at 9th and above." },
  { id: "mu-1-mending", name: "Mending", level: 1, class: "Magic User", range: "3\"", duration: "Permanent", areaOfEffect: "One object", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 68, description: "This spell repairs small breaks or tears in objects (cloth, leather, chain links, a broken ring, medallion, cup, staff, wand, etc.). It will weld broken metallic objects such as a ring, chain, medallion, or slender rod — if the damaged area is not larger than 1 cubic inch. Ceramic or wooden objects with multiple breaks can be invisibly rejoined to be as strong as new. A hole in a leather sack or wineskin is cause for the spell to mend it." },
  { id: "mu-1-message", name: "Message", level: 1, class: "Magic User", range: "6\" + 1\"/level", duration: "5 rounds/level", areaOfEffect: "One creature", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 68, description: "When this spell is cast, the magic-user can whisper messages and receive whispered replies with little chance of being overheard. The magic-user points his or her finger at each creature to be included in the spell effect. When the magic-user whispers the desired message, it is heard by those indicated. The material component is a short piece of copper wire." },
  { id: "mu-1-nystuls-magic-aura", name: "Nystul's Magic Aura", level: 1, class: "Magic User", range: "Touch", duration: "1 day/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 round", savingThrow: "Special", phbPage: 68, description: "By means of this spell, any one item of no more than 5 lb. weight per level of the magic-user can be given an aura that is noticed if detection of magic is exercised. If the object bearing Nystul's magic aura is actually magical, the power will displace its aura. The material component for this spell is a small square of silk, which must be passed over the object to bear the aura." },
  { id: "mu-1-protection-from-evil", name: "Protection from Evil", level: 1, class: "Magic User", range: "Touch", duration: "2 rounds/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 69, description: "When this spell is cast, it creates a magical barrier around the recipient which moves with the recipient. The barrier has three effects: First, all attacks made by evil or evilly enchanted creatures against the protected creature suffer -2 penalties to attack rolls, and the protected creature makes its saving throws from such attacks at +2. Second, any attempts to possess or exercise mental control over the protected creature are blocked. Third, summoned or created creatures cannot touch the protected creature." },
  { id: "mu-1-push", name: "Push", level: 1, class: "Magic User", range: "1\" + 1\"/level", duration: "Instantaneous", areaOfEffect: "Special", components: "V, S, M", castingTime: "1", savingThrow: "Neg.", phbPage: 69, description: "Upon pronouncing the syllables of this spell, the magic-user causes an invisible force to strike a target creature or object. This force is enough to push a creature or object a short distance away. It can also be used to push open doors, move boulders, or accomplish other tasks requiring pushing. The material component is a small pebble which must be hurled at the target, and the spell will affect an object of up to 50 lb per level." },
  { id: "mu-1-read-magic", name: "Read Magic", level: 1, class: "Magic User", range: "0", duration: "2 rounds/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 round", savingThrow: "None", phbPage: 69, description: "By means of a read magic spell, the magic-user is able to read magical inscriptions on objects — books, scrolls, weapons, and the like — that would otherwise be totally unintelligible. This deciphering does not invoke the magic contained in the writing, although it may do so in the case of a cursed scroll. The material components for the spell are a clear crystal or mineral prism, which is not expended." },
  { id: "mu-1-shield", name: "Shield", level: 1, class: "Magic User", range: "0", duration: "5 rounds/level", areaOfEffect: "Special", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 69, description: "When this spell is cast, an invisible barrier comes into being in front of the magic-user. This shield totally negates magic missile attacks. It provides the equivalent of AC 2 against hand-hurled missiles (axes, darts, javelins, spears, and such), AC 3 against small device-propelled missiles (arrows, bolts, bullets, manticore spikes, and so forth), and AC 4 against all other forms of attack." },
  { id: "mu-1-shocking-grasp", name: "Shocking Grasp", level: 1, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "Creature touched", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 69, description: "When the magic-user casts this spell, he or she develops a powerful electrical charge that gives a jolt to the creature touched. The magic-user must touch a creature or conductive material, and if touching an armored or otherwise accoutered opponent, the magic-user can make a roll to hit as if he or she were a fighter (using the attack roll tables for fighters). The spell does 1d8 points of damage plus 1 point per level of the magic-user." },
  { id: "mu-1-sleep", name: "Sleep", level: 1, class: "Magic User", range: "3\" + 1\"/level", duration: "5 rounds/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 70, description: "When a sleep spell is cast, it affects a creature or creatures in an area of effect according to their hit dice. The spell will put to sleep creatures with a total of up to 4+level hit dice, beginning with those with the fewest hit dice. Creatures with 4+3 or more hit dice are not affected. Sleeping creatures are helpless and can be killed with a single blow. The material component is a pinch of fine sand, rose petals, or a live cricket." },
  { id: "mu-1-spider-climb", name: "Spider Climb", level: 1, class: "Magic User", range: "Touch", duration: "3 rounds + 1 round/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "1", savingThrow: "Neg.", phbPage: 70, description: "A spider climb spell enables the recipient of the magic to climb and travel upon vertical surfaces as well as a giant spider, i.e., at 6\" movement rate, or hang upside down from ceilings. Unwilling victims must be touched and are allowed a saving throw vs. spell to avoid the effect of the spell. The material components of this spell are a drop of bitumen and a live spider, both of which must be eaten by the spell recipient." },
  { id: "mu-1-tensers-floating-disc", name: "Tenser's Floating Disc", level: 1, class: "Magic User", range: "2\"", duration: "3 turns + 1 turn/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 70, description: "With this spell, the caster creates the slightly concave, circular plane of force known as Tenser's floating disc (after the famed wizard whose disc is so named). The disc is 3 feet in diameter and holds 100 lbs. per level of the magic-user. It remains stationary unless the magic-user moves, in which case it follows at a 6\" speed. The material component is a drop of mercury." },
  { id: "mu-1-unseen-servant", name: "Unseen Servant", level: 1, class: "Magic User", range: "0", duration: "1 hour + 1 turn/level", areaOfEffect: "3\" radius", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 70, description: "The unseen servant is a creation of magical force that performs simple tasks at the command of the magic-user. It can be used to hold a door shut, clean and mend clothes, serve food and drink, hold torch, carry items, open doors, or perform other simple tasks that require the use of hands. The servant has no attack capability, but it can be used to shield the magic-user from view. The material components are a piece of string and a bit of wood." },
  { id: "mu-1-ventriloquism", name: "Ventriloquism", level: 1, class: "Magic User", range: "1\"/level", duration: "4 rounds + 1 round/level", areaOfEffect: "Special", components: "V, M", castingTime: "1", savingThrow: "None", phbPage: 71, description: "This spell enables the magic-user to make his or her voice — or that of any individual he or she wishes — sound from any location with the spell's range. The illusion can be made to sound like any voice or sound that the magic-user is familiar with. The material component of the spell is a small cone of parchment." },
  { id: "mu-1-write", name: "Write", level: 1, class: "Magic User", range: "0", duration: "1 hour/level", areaOfEffect: "One magical writing", components: "V, S, M", castingTime: "1 round", savingThrow: "Special", phbPage: 71, description: "With this spell, the magic-user can inscribe a magical formula (spell) that he or she does not understand, and the writing is done in the caster's own language. When the formula is completed — which takes as long as it would take to write out the spell — the spell is complete in scroll form. The material components of the spell are rare inks costing not less than 200 gp per page of the spell to be inscribed." },
  { id: "mu-2-audible-glamer", name: "Audible Glamer", level: 2, class: "Magic User", range: "6\" + 1\"/level", duration: "2 rounds/level", areaOfEffect: "Hearing range", components: "V, S, M", castingTime: "2", savingThrow: "Special", phbPage: 71, description: "When the audible glamer spell is cast, the magic-user causes a volume of sound to arise, at whatever distance he or she desires, up to the spell's range, and seem to recede, approach, or remain at a fixed place as desired. The noise created by audible glamer can be that of a person or persons talking, thunder, running water, winds, a fight, etc." },
  { id: "mu-2-continual-light", name: "Continual Light", level: 2, class: "Magic User", range: "6\"", duration: "Permanent", areaOfEffect: "6\" radius globe", components: "V, S", castingTime: "2", savingThrow: "Special", phbPage: 71, description: "This spell is the same as the first level cleric spell, continual light, except that it is not reversible and is permanent. The light shed by this spell is equal to that of a light spell, i.e., the light of a torch. The spell can be centered on an object, a point in space, or a creature, and it moves with the object or creature centered upon." },
  { id: "mu-2-darkness-15", name: "Darkness, 15' Radius", level: 2, class: "Magic User", range: "1\"/level", duration: "1 round/level + 1 round", areaOfEffect: "15' radius", components: "V, M", castingTime: "2", savingThrow: "None", phbPage: 72, description: "This spell causes total, impenetrable darkness in the area of effect. Even infravision is unable to penetrate it. It can be cast at a specific point or object, and all creatures are blinded by it. The spell can be negated by a light spell cast on the same area. The material component is a bit of bat fur and either a drop of pitch or a piece of coal." },
  { id: "mu-2-detect-evil", name: "Detect Evil", level: 2, class: "Magic User", range: "0", duration: "5 rounds/level", areaOfEffect: "1\" path, 6\" long", components: "V, S", castingTime: "2", savingThrow: "None", phbPage: 72, description: "This spell discovers emanations of evil, or of good if the magic-user is evil, from any creature, object, or area. Character alignment is not necessarily detected by this spell. The dweomer radiates evil if it has been enchanted by an evil magic-user. Gods and their servants of evil alignment radiate evil." },
  { id: "mu-2-detect-invisibility", name: "Detect Invisibility", level: 2, class: "Magic User", range: "1\"/level", duration: "5 rounds/level", areaOfEffect: "1\" path", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 72, description: "When the magic-user casts a detect invisibility spell, he or she is able to see clearly any objects or beings which are invisible, as well as any which are astral, ethereal, or out of phase. In addition, it enables the magic-user to detect hidden or concealed creatures (thieves in shadows, etc.). The material components are a pinch of talc and a small sprinkling of powdered silver." },
  { id: "mu-2-esp", name: "ESP", level: 2, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "3\" range", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 72, description: "When an ESP spell is cast, the magic-user is able to detect the surface thoughts of any creatures in range — except undead and creatures without minds (as golems). The magic-user is able to understand the thoughts of creatures of any language. The material component of this spell is a copper coin." },
  { id: "mu-2-forget", name: "Forget", level: 2, class: "Magic User", range: "3\"", duration: "Permanent", areaOfEffect: "1-4 creatures in a 2\" x 2\" area", components: "V, S", castingTime: "2", savingThrow: "Neg.", phbPage: 72, description: "By means of this spell, the magic-user causes the recipient creature(s) to forget the events of the previous round (the one minute of time before the casting of the forget spell). The forget spell does not induce sleep or affect the creature's intelligence. Affected creatures can remember nothing from the prior round. A saving throw vs. spell negates the spell." },
  { id: "mu-2-invisibility", name: "Invisibility", level: 2, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 73, description: "This spell causes the recipient to vanish from sight and be undetectable by normal vision or infravision. Not even the aided eyes of an elf can see an invisible creature. Of course, the invisible creature is not magically silenced, and certain other conditions can render the creature detectable. The material components of the invisibility spell are an eyelash and a bit of gum arabic." },
  { id: "mu-2-knock", name: "Knock", level: 2, class: "Magic User", range: "6\"", duration: "Special", areaOfEffect: "10 sq. ft./level", components: "V", castingTime: "1", savingThrow: "None", phbPage: 73, description: "The knock spell opens stuck, barred, locked, held, or wizard locked doors. It opens secret doors, as well as locked or trick-opening boxes or chests. It also loosens welds, shackles, or chains. If used to open a wizard locked door, the knock does not remove the former spell, but simply suspends its functioning for one turn. The spell causes a loud knocking sound." },
  { id: "mu-2-levitate", name: "Levitate", level: 2, class: "Magic User", range: "2\"/level", duration: "1 turn/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "2", savingThrow: "Neg.", phbPage: 73, description: "When a levitate spell is cast, the magic-user can place it upon his or her person, an object, or a single creature, subject to a maximum weight limit of 100 lbs. per level of experience. If the spell is cast upon the magic-user, he or she can move vertically up or down at a movement rate of 2\" per round. The material component of this spell is either a small leather loop or a piece of golden wire bent into a cup shape with a long shank on the bottom." },
  { id: "mu-2-locate-object", name: "Locate Object", level: 2, class: "Magic User", range: "2\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 73, description: "This spell aids in locating a known or familiar object. The magic-user casts the spell, slowly turns, and will sense when he or she is facing in the direction of the object to be located. The material components are a forked twig and a bit of lodestone." },
  { id: "mu-2-magic-mouth", name: "Magic Mouth", level: 2, class: "Magic User", range: "Special", duration: "Special", areaOfEffect: "One object", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 74, description: "When this spell is cast, the magic-user empowers the chosen object with an enchanted mouth that suddenly appears and speaks a message when a specified event occurs. The message can be of up to 25 words, and in any language known by the spell caster. The material component is a small bit of honeycomb." },
  { id: "mu-2-melfs-acid-arrow", name: "Melf's Acid Arrow", level: 2, class: "Magic User", range: "18\"", duration: "Special", areaOfEffect: "One creature", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 73, description: "By means of this spell, the magic-user creates a magical arrow that speeds to its target as if fired from the bow of a fighter. The arrow strikes unerringly (subject to spell immunity, globe of invulnerability, etc.) and inflicts 2d4 hit points of damage. It continues to burn for additional rounds: 2 rounds at 2d4 damage per round at 3rd level, up to a maximum of 4 rounds." },
  { id: "mu-2-mirror-image", name: "Mirror Image", level: 2, class: "Magic User", range: "0", duration: "2 rounds/level", areaOfEffect: "6' radius", components: "V, S", castingTime: "2", savingThrow: "None", phbPage: 74, description: "When a mirror image spell is cast, between two and five exact duplicates of the magic-user appear. The images perform the same actions as the magic-user and are dispelled with a single attack. The images last for the duration or until destroyed. An attacker must select one of the images to attack (randomly); if they hit an image it is destroyed, otherwise the attack lands on an image and the magic-user is unaffected." },
  { id: "mu-2-pyrotechnics", name: "Pyrotechnics", level: 2, class: "Magic User", range: "12\"", duration: "Special", areaOfEffect: "10 or 100 times the fire source", components: "V, S, M", castingTime: "2", savingThrow: "Neg.", phbPage: 74, description: "A pyrotechnics spell turns a fire of any size into either a burst of blinding fireworks or a thick cloud of choking smoke, at the option of the magic-user. Fireworks blinds creatures within 12\" for 1d4+1 rounds; smoke fills a 20' cube around the fire and obscures vision for 1d4+1 rounds." },
  { id: "mu-2-ray-of-enfeeblement", name: "Ray of Enfeeblement", level: 2, class: "Magic User", range: "1\" + 1\"/4 levels", duration: "1 round/level", areaOfEffect: "One creature", components: "V, S", castingTime: "2", savingThrow: "Neg.", phbPage: 74, description: "By means of this spell, the magic-user enfeeebles an enemy creature by means of a ray which causes the target to lose 25% + 2% per level of the magic-user of Strength (which effects to hit rolls, damage adjustment, weight allowance, etc.). A saving throw vs. spell negates the effect." },
  { id: "mu-2-rope-trick", name: "Rope Trick", level: 2, class: "Magic User", range: "Touch", duration: "2 turns/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "2", savingThrow: "None", phbPage: 74, description: "When this spell is cast upon a piece of rope from 5 to 30 feet long, one end of the rope rises into the air until the whole rope hangs perpendicular to the ground. An extradimensional space is created at the upper end of the rope. The space can hold up to 6 persons. The material component is powdered corn extract and a twisted loop of parchment." },
  { id: "mu-2-scare", name: "Scare", level: 2, class: "Magic User", range: "3\"/level", duration: "3d4 rounds", areaOfEffect: "One creature", components: "V, S, M", castingTime: "2", savingThrow: "Neg.", phbPage: 75, description: "When this spell is cast, the magic-user causes the recipient to become frightened and flee in panic. Creatures with 6 or more hit dice are unaffected. A successful saving throw vs. spell negates the effect. The material component is a bit of bone from an undead skeleton, zombie, ghoul, ghast, or mummy." },
  { id: "mu-2-shatter", name: "Shatter", level: 2, class: "Magic User", range: "3\"/level", duration: "Instantaneous", areaOfEffect: "3' radius", components: "V, S, M", castingTime: "2", savingThrow: "Neg.", phbPage: 75, description: "The shatter spell affects non-magical objects of crystal, glass, ceramic, or porcelain — such as vials, bottles, flasks, jugs, mirrors, and windows. It causes these items to shatter. The material component is a chip of mica." },
  { id: "mu-2-stinking-cloud", name: "Stinking Cloud", level: 2, class: "Magic User", range: "3\"", duration: "1 round/level", areaOfEffect: "2\" x 2\" x 2\" cloud", components: "V, S, M", castingTime: "2", savingThrow: "Special", phbPage: 75, description: "When a stinking cloud is cast, the magic-user creates a billowing mass of nauseous vapors up to 3\" distant from his or her position. Any creature caught within the cloud must save vs. poison or be helpless (unable to attack or flee) for 2d4 rounds after leaving the cloud. The material component of the spell is a rotten egg or several skunk cabbage leaves." },
  { id: "mu-2-strength", name: "Strength", level: 2, class: "Magic User", range: "Touch", duration: "1 hour/level", areaOfEffect: "Person touched", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 75, description: "Application of this spell increases the Strength of the character by a number of points — or tenths of points for characters with 18 Strength. Fighters (including paladins and rangers) gain 1d8 points of Strength; clerics gain 1d6 points; and thieves (including assassins and bards) and magic-users gain 1d4 points. The material component is a few hairs, or a pinch of dung, from a particularly strong animal." },
  { id: "mu-2-web", name: "Web", level: 2, class: "Magic User", range: "1\"/level", duration: "2 turns/level", areaOfEffect: "8,000 cubic feet", components: "V, S, M", castingTime: "2", savingThrow: "Neg.", phbPage: 76, description: "A web spell creates a many-layered mass of strong, sticky strands similar to spider webs but far larger and tougher. These masses must be anchored to two or more solid and diametrically opposed points. Any creature caught within a web becomes entangled among the gluey fibers. The material component is a bit of spider web." },
  { id: "mu-2-wizard-lock", name: "Wizard Lock", level: 2, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "30 sq. ft./level", components: "V, S", castingTime: "2", savingThrow: "None", phbPage: 76, description: "A wizard lock spell cast upon a door, chest, or portal magically locks it. The magic-user can freely pass his or her own wizard lock without affecting it; otherwise, the wizard lock can be opened only by a knock spell (which will not permanently remove the dweomer), a magic-user 4 or more levels higher than the one who cast the spell, or a dispel magic." },
  { id: "mu-3-blink", name: "Blink", level: 3, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "Personal", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 76, description: "By means of this spell, the magic-user randomly teleports, along with all gear worn or carried, to a nearby spot." },
  { id: "mu-3-clairaudience", name: "Clairaudience", level: 3, class: "Magic User", range: "Unlimited", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 76, description: "The clairaudience spell enables the magic-user to concentrate upon some locale and hear, as if he or she were standing in that spot, whatever sound occurs there." },
  { id: "mu-3-clairvoyance", name: "Clairvoyance", level: 3, class: "Magic User", range: "Unlimited", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 77, description: "Similar to the clairaudience spell, the clairvoyance spell empowers the magic-user to see in his or her mind whatever is visible from some other locale." },
  { id: "mu-3-dispel-magic", name: "Dispel Magic", level: 3, class: "Magic User", range: "12\"", duration: "Instantaneous", areaOfEffect: "3\" x 3\"", components: "V, S", castingTime: "3", savingThrow: "None", phbPage: 77, description: "When a dispel magic spell is cast, it neutralizes or negates the magic it comes in contact with as follows: It will affect all magic used to create an ongoing effect if the caster succeeds." },
  { id: "mu-3-explosive-runes", name: "Explosive Runes", level: 3, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "1\" radius", components: "V, S", castingTime: "3", savingThrow: "None", phbPage: 77, description: "By tracing these mystic runes upon a book, map, scroll, or similar object bearing written information, the magic-user prevents unauthorized persons from reading his or her work." },
  { id: "mu-3-feign-death", name: "Feign Death", level: 3, class: "Magic User", range: "Touch", duration: "1 turn + 1 round/level", areaOfEffect: "Person touched", components: "V, S", castingTime: "1 segment", savingThrow: "None", phbPage: 77, description: "This spell can be cast only upon a willing person (or the magic-user himself or herself). The feign death spell causes the recipient to appear to be dead." },
  { id: "mu-3-fireball", name: "Fireball", level: 3, class: "Magic User", range: "10\" + 1\"/level", duration: "Instantaneous", areaOfEffect: "2\" radius sphere", components: "V, S, M", castingTime: "3", savingThrow: "1/2", phbPage: 77, description: "A fireball is an explosive burst of flame which detonates with a low roar and delivers damage proportional to the level of the magic-user who cast it, i.e., 1 six-sided die (d6) for each level of experience of the spell caster. Exception: Optionally, the spell can be cast as a cone or a straight-line flame. The damage inflicted is 1d6 per level of the caster." },
  { id: "mu-3-fly", name: "Fly", level: 3, class: "Magic User", range: "Touch", duration: "1 turn/level + 1d6 turns", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 78, description: "This spell bestows the power of magical flight. The creature affected is able to move vertically and horizontally at a rate of 12\" (120 feet per round). The material component is a wing feather of any bird." },
  { id: "mu-3-gust-of-wind", name: "Gust of Wind", level: 3, class: "Magic User", range: "0", duration: "1 round", areaOfEffect: "1\" x 10\" path", components: "V, S, M", castingTime: "3", savingThrow: "Neg.", phbPage: 78, description: "When this spell is cast, a strong puff of air originates from the magic-user and moves in the direction he or she is facing. The force of this gust of wind (of hurricane force) is sufficient to extinguish candles, torches, and similar unprotected flames." },
  { id: "mu-3-haste", name: "Haste", level: 3, class: "Magic User", range: "6\"", duration: "3 rounds + 1 round/level", areaOfEffect: "4\" x 4\" area, 1 creature/level", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 78, description: "When a haste spell is cast, affected creatures function at double their normal movement and attack rates. Thus, a creature moving at 6\" and attacking once per round would move at 12\" and attack twice per round. The material component is a shaving of licorice root." },
  { id: "mu-3-hold-person", name: "Hold Person", level: 3, class: "Magic User", range: "12\"", duration: "2 rounds/level", areaOfEffect: "One to four persons", components: "V, S, M", castingTime: "3", savingThrow: "Neg.", phbPage: 78, description: "This spell holds 1-4 humans, demi-humans, or humanoid creatures rigidly immobile and in place for the spell duration. The material component for this spell is a small straight piece of iron." },
  { id: "mu-3-infravision", name: "Infravision", level: 3, class: "Magic User", range: "Touch", duration: "2 hours + 1 hour/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "1 round", savingThrow: "None", phbPage: 79, description: "By means of this spell, the magic-user enables the recipient to see in the infra-red spectrum, i.e., the creature is able to see heat radiation. The material component is either a pinch of dried carrot or an agate." },
  { id: "mu-3-invisibility-10-foot", name: "Invisibility, 10' Radius", level: 3, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "10' radius", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 79, description: "This spell confers invisibility upon all creatures within 10 feet of the recipient. Included in the spell is the personal effects of those becoming invisible. The material components are the same as for the invisibility spell: an eyelash and a bit of gum arabic." },
  { id: "mu-3-item", name: "Item", level: 3, class: "Magic User", range: "Touch", duration: "4 hours/level", areaOfEffect: "2 cu. ft./level", components: "V, S, M", castingTime: "3", savingThrow: "Special", phbPage: 79, description: "By means of this spell, the magic-user is able to touch a normal, non-magical item of a size up to 2 cubic feet per level and cause it to shrink to 1/12 of its normal size." },
  { id: "mu-3-lightning-bolt", name: "Lightning Bolt", level: 3, class: "Magic User", range: "4\" + 1\"/level", duration: "Instantaneous", areaOfEffect: "Special", components: "V, S, M", castingTime: "3", savingThrow: "1/2", phbPage: 79, description: "Upon casting this spell, the magic-user releases a powerful stroke of electrical energy that inflicts 1d6 points of damage per level of the spell caster. The lightning bolt may set fire to combustibles, melt metals, or fuse rock. The material components are a bit of fur and an amber, crystal, or glass rod." },
  { id: "mu-3-monster-summoning-1", name: "Monster Summoning I", level: 3, class: "Magic User", range: "3\"", duration: "2 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 80, description: "Within 1 round after this spell is cast, 2d4 first level monsters appear. These monsters serve the magic-user and can be compelled to fight for the caster." },
  { id: "mu-3-phantasmal-force", name: "Phantasmal Force", level: 3, class: "Magic User", range: "8\" + 1\"/level", duration: "Special", areaOfEffect: "8 sq. ft. + 1 sq. ft./level", components: "V, S, M", castingTime: "3", savingThrow: "Special", phbPage: 80, description: "This spell creates the illusion of any object, creature, or force, as long as it is within the boundaries of the spell's area of effect. The cast illusion does not create sound, smell, texture, or temperature. The material component of the spell is a bit of fleece." },
  { id: "mu-3-protection-from-evil-10-foot", name: "Protection from Evil, 10' Radius", level: 3, class: "Magic User", range: "Touch", duration: "2 rounds/level", areaOfEffect: "10' radius", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 80, description: "The globe of protection of this spell is identical in effect to a protection from evil spell, except that it encompasses a much larger area and everyone within 10 feet of the spell recipient is protected." },
  { id: "mu-3-protection-from-normal-missiles", name: "Protection from Normal Missiles", level: 3, class: "Magic User", range: "Touch", duration: "1 turn/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "3", savingThrow: "None", phbPage: 80, description: "By means of this spell, the magic-user bestows total invulnerability to hurled and hand-propelled missiles such as arrows, axes, bolts, javelins, small stones, spears, etc. upon the recipient." },
  { id: "mu-3-slow", name: "Slow", level: 3, class: "Magic User", range: "9\" + 1\"/level", duration: "3 rounds + 1 round/level", areaOfEffect: "4\" x 4\" area, 1 creature/level", components: "V, S, M", castingTime: "3", savingThrow: "Neg.", phbPage: 81, description: "A slow spell causes affected creatures to move and attack at half normal rates (half-speed movement and one attack per two rounds). The material component is a drop of molasses." },
  { id: "mu-3-suggestion", name: "Suggestion", level: 3, class: "Magic User", range: "3\"", duration: "4 hours + 4 hours/level", areaOfEffect: "One creature", components: "V, M", castingTime: "3", savingThrow: "Neg.", phbPage: 81, description: "When this spell is cast by the magic-user, he or she influences the actions of the chosen recipient by utterance of a few words — phrases or a sentence or two — suggesting a course of action desirable to the spell caster. The material component is a snake's tongue and either a bit of honeycomb or a drop of sweet oil." },
  { id: "mu-3-tongues", name: "Tongues", level: 3, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "6\" radius", components: "V, M", castingTime: "3", savingThrow: "None", phbPage: 81, description: "This spell enables the magic-user to speak and understand additional languages, whether they are racial tongues or regional dialects, but not including secret languages such as thieves' cant or druidic. The material component is a small clay model of a ziggurat, which shatters when the spell is pronounced." },
  { id: "mu-3-water-breathing", name: "Water Breathing", level: 3, class: "Magic User", range: "Touch", duration: "1 hour/level", areaOfEffect: "Creature touched", components: "V, S", castingTime: "3", savingThrow: "None", phbPage: 81, description: "The recipient of a water breathing spell is able to breathe water freely for the duration of the spell. The spell does not make the recipient unable to breathe air." },
  { id: "mu-4-charm-monster", name: "Charm Monster", level: 4, class: "Magic User", range: "6\"", duration: "Special", areaOfEffect: "One or more creatures in a 2\" radius", components: "V, S", castingTime: "4", savingThrow: "Neg.", phbPage: 81, description: "This spell is the same as charm person, except that it will affect any living creature — or several low-level creatures. The spell affects 2d4 creatures of 1-3 hit dice, 1d4 creatures of 4-6 hit dice, or just one creature of 7 or more hit dice." },
  { id: "mu-4-confusion", name: "Confusion", level: 4, class: "Magic User", range: "12\"", duration: "2 rounds + 1 round/level", areaOfEffect: "Up to 6\" x 6\" area", components: "V, S, M", castingTime: "4", savingThrow: "Special", phbPage: 82, description: "This spell causes confusion in one or more creatures within the area, creating indecision and the inability to take effective action. The spell affects 2d4 creatures, plus 1 per level of the magic-user." },
  { id: "mu-4-dig", name: "Dig", level: 4, class: "Magic User", range: "3\"", duration: "1 round/level", areaOfEffect: "5' cube/round", components: "V, S, M", castingTime: "4", savingThrow: "Neg.", phbPage: 82, description: "A dig spell enables the magic-user to excavate 125 cubic feet (a 5-foot cube) of earth, sand, or mud per round, or 40 cubic feet (an approximately 3.5 by 3.5 by 3.5 foot cube) of harder materials such as rock." },
  { id: "mu-4-dimension-door", name: "Dimension Door", level: 4, class: "Magic User", range: "0", duration: "Instantaneous", areaOfEffect: "Special", components: "V", castingTime: "1", savingThrow: "None", phbPage: 82, description: "By means of a dimension door spell, the magic-user instantly transfers himself or herself, or any single creature of man-size or smaller, to any known place within 3\" per level of the magic-user." },
  { id: "mu-4-enchanted-weapon", name: "Enchanted Weapon", level: 4, class: "Magic User", range: "Touch", duration: "5 rounds/level", areaOfEffect: "Weapon touched", components: "V, S", castingTime: "1 turn", savingThrow: "None", phbPage: 82, description: "This spell turns an ordinary weapon into a magical one. The weapon is the equivalent of a +1 weapon and can hit creatures requiring magical weapons to hit." },
  { id: "mu-4-extension-1", name: "Extension I", level: 4, class: "Magic User", range: "0", duration: "Special", areaOfEffect: "Special", components: "V", castingTime: "2", savingThrow: "None", phbPage: 83, description: "By use of an extension I spell, the magic-user prolongs the duration of a previously cast first, second, or third level spell by 50%. Thus, a fly spell lasting 10 turns could be extended to 15 turns." },
  { id: "mu-4-fear", name: "Fear", level: 4, class: "Magic User", range: "0", duration: "Special", areaOfEffect: "6\" long cone, 3\" diameter at end", components: "V, S, M", castingTime: "4", savingThrow: "Neg.", phbPage: 83, description: "When a fear spell is cast, the magic-user sends forth an invisible cone of terror that causes creatures within its area of effect to turn away from the magic-user and flee." },
  { id: "mu-4-fire-charm", name: "Fire Charm", level: 4, class: "Magic User", range: "1\"", duration: "2 rounds/level", areaOfEffect: "15' radius", components: "V, S, M", castingTime: "4", savingThrow: "Neg.", phbPage: 83, description: "By means of this spell, the magic-user causes a normal fire source to serve as a tool for enchanting creatures. Any creature looking at the fire must make a saving throw or be captivated by the dancing flames." },
  { id: "mu-4-fire-shield", name: "Fire Shield", level: 4, class: "Magic User", range: "0", duration: "2 rounds + 1 round/level", areaOfEffect: "Personal", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 83, description: "This spell is variant: Warm Shield — protects against cold-based attacks; Chill Shield — protects against fire-based attacks. In both cases, the shield provides protection against normal missiles and magic missile attacks." },
  { id: "mu-4-fire-trap", name: "Fire Trap", level: 4, class: "Magic User", range: "Touch", duration: "Permanent until discharged", areaOfEffect: "Object touched", components: "V, S, M", castingTime: "1 turn", savingThrow: "1/2", phbPage: 83, description: "Any closable item (book, box, bottle, chest, coffer, coffin, door, drawer, etc.) can be warded by a fire trap spell. The spell is cast upon the item. When the warded object is opened by someone other than the spell caster, a fiery explosion erupts causing 1d4 points of damage plus 1 point per level of the magic-user." },
  { id: "mu-4-fumble", name: "Fumble", level: 4, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "One creature", components: "V, S, M", castingTime: "4", savingThrow: "Special", phbPage: 84, description: "When a fumble spell is cast, the subject creature stumbles and falls, spilling anything it was carrying. If the target fails its saving throw vs. spell, it is so affected. If the saving throw succeeds, the creature moves at half normal speed for the spell duration." },
  { id: "mu-4-hallucinatory-terrain", name: "Hallucinatory Terrain", level: 4, class: "Magic User", range: "2\"/level", duration: "Until touched or dispelled", areaOfEffect: "1\" x 1\"/level area", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 84, description: "By means of this spell, the magic-user makes one type of terrain appear like another. Thus, an open plain can be made to look like a forest, swamp, or other terrain." },
  { id: "mu-4-ice-storm", name: "Ice Storm", level: 4, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "4\" x 4\" area", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 84, description: "When this spell is cast, great hailstones pound down in the area of effect or the spell is cast as driving sleet in an area up to 4\" by 4\". In either case, the material component is a pinch of dust and a few drops of water." },
  { id: "mu-4-massmorph", name: "Massmorph", level: 4, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "11 or more man-sized creatures", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 84, description: "When this spell is cast upon willing creatures of man-size or smaller, up to 10 creatures per level of the magic-user are caused to appear as trees or shrubs." },
  { id: "mu-4-minor-globe-of-invulnerability", name: "Minor Globe of Invulnerability", level: 4, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "5' radius around caster", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 84, description: "This spell creates an immobile, faintly shimmering magical sphere around the caster that prevents any first, second, or third level spell effects from penetrating." },
  { id: "mu-4-monster-summoning-2", name: "Monster Summoning II", level: 4, class: "Magic User", range: "3\"", duration: "3 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 85, description: "This spell is similar to the third level monster summoning I spell, except that this spell summons 1d6 second level monsters. These appear within the spell's range and attack the magic-user's opponents." },
  { id: "mu-4-plant-growth", name: "Plant Growth", level: 4, class: "Magic User", range: "1\"/level", duration: "Permanent", areaOfEffect: "Up to 200 sq. ft./level", components: "V, S", castingTime: "4", savingThrow: "None", phbPage: 85, description: "When a plant growth spell is cast, the magic-user causes normal brush or woods in the spell's area of effect to become thick and overgrown and entangled." },
  { id: "mu-4-polymorph-other", name: "Polymorph Other", level: 4, class: "Magic User", range: "1\"/level", duration: "Permanent", areaOfEffect: "One creature", components: "V, S, M", castingTime: "4", savingThrow: "Neg.", phbPage: 85, description: "The polymorph other spell will change one creature into another creature of the caster's choice, for example, turning a human fighter into a frog. The changes are permanent." },
  { id: "mu-4-polymorph-self", name: "Polymorph Self", level: 4, class: "Magic User", range: "0", duration: "2 turns/level", areaOfEffect: "Personal", components: "V", castingTime: "4", savingThrow: "None", phbPage: 85, description: "When this spell is cast, the magic-user is able to assume the form of any creature from as small as a wren to as large as a hippopotamus, including the creature's physical capabilities." },
  { id: "mu-4-remove-curse", name: "Remove Curse", level: 4, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "Special", components: "V, S", castingTime: "4", savingThrow: "Special", phbPage: 86, description: "Upon casting this spell, the magic-user is usually able to remove a curse — whether it is on an object, a person, or in the form of some undesired sending or evil presence." },
  { id: "mu-4-rary's-mnemonic-enhancer", name: "Rary's Mnemonic Enhancer", level: 4, class: "Magic User", range: "0", duration: "1 day", areaOfEffect: "Personal", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 86, description: "By means of this spell, the magic-user is able to memorize, or retain the memory of, three additional spell levels, i.e., three additional first level spells, or two second level and one first level spell, etc." },
  { id: "mu-4-shout", name: "Shout", level: 4, class: "Magic User", range: "0", duration: "Instantaneous", areaOfEffect: "10' x 30' cone", components: "V", castingTime: "1", savingThrow: "Special", phbPage: 86, description: "When a shout spell is cast, the magic-user emits an ear-splitting shriek, which is able to injure and possibly deafen those in the area of effect. The sound requires a saving throw vs. spell or the creature becomes deaf." },
  { id: "mu-4-wall-of-fire", name: "Wall of Fire", level: 4, class: "Magic User", range: "6\"", duration: "Special", areaOfEffect: "Special", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 86, description: "The wall of fire spell brings forth an immobile, blazing curtain of magical fire of shimmering color — yellow-green or amber. The spell causes 2d4 hit points to any creature passing through it." },
  { id: "mu-4-wall-of-ice", name: "Wall of Ice", level: 4, class: "Magic User", range: "1\"/level", duration: "1 turn/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "4", savingThrow: "None", phbPage: 86, description: "This spell enables the magic-user to create either an anchored plane of ice or a hemisphere of ice. Either form can be used to entrap opponents." },
  { id: "mu-4-wizard-eye", name: "Wizard Eye", level: 4, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 86, description: "When this spell is employed, the magic-user creates an invisible sensory organ that sends him or her visual information. The magic-user can see up to 2\" distant in dim illumination with the wizard eye, so it can travel up to this distance from the spell caster." },
  { id: "mu-5-airy-water", name: "Airy Water", level: 5, class: "Magic User", range: "0", duration: "1 turn/level", areaOfEffect: "10' radius sphere or 20' radius hemisphere", components: "V, M", castingTime: "5", savingThrow: "None", phbPage: 87, description: "The magic-user converts water (or similar liquid) in the area of effect into a less dense substance akin to air. Creatures can breathe and move freely through the area." },
  { id: "mu-5-animate-dead", name: "Animate Dead", level: 5, class: "Magic User", range: "1\"", duration: "Permanent", areaOfEffect: "Special", components: "V, S, M", castingTime: "5 rounds", savingThrow: "None", phbPage: 87, description: "This spell creates the lowest forms of undead magic: skeletons or zombies (see Monster Manual). The magic-user may animate 1 skeleton or zombie per level of experience. These undead obey simple instructions from the caster." },
  { id: "mu-5-bigbys-interposing-hand", name: "Bigby's Interposing Hand", level: 5, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 87, description: "Bigby's interposing hand creates a man-sized to gargantuan-sized magical hand which interposes itself between the spell caster and an opponent." },
  { id: "mu-5-cloudkill", name: "Cloudkill", level: 5, class: "Magic User", range: "1\"", duration: "1 round/level", areaOfEffect: "4\" wide, 2\" high, 2\" deep cloud", components: "V, S", castingTime: "5", savingThrow: "None", phbPage: 87, description: "This spell generates a billowing cloud of ghastly yellowish-green vapors that is so toxic as to slay any creature with fewer than 5 hit dice, cause creatures with 5 or 6 hit dice to save vs. poison at -4 or be slain, and weaken creatures of 7 or more hit dice." },
  { id: "mu-5-cone-of-cold", name: "Cone of Cold", level: 5, class: "Magic User", range: "0", duration: "Instantaneous", areaOfEffect: "Special cone shape", components: "V, S, M", castingTime: "5", savingThrow: "1/2", phbPage: 88, description: "When this spell is cast, it causes a cone-shaped area of extreme cold, originating at the magic-user's hand, to flash out. Length of the cone is 1\" per level of the spell caster, and the base diameter is 1\" for every 2 levels. The cold inflicts 1d4+1 hit points of damage per level of the magic-user." },
  { id: "mu-5-conjure-elemental", name: "Conjure Elemental", level: 5, class: "Magic User", range: "6\"", duration: "1 turn/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 88, description: "There are actually four conjure elemental spells, one for each elemental type: air, earth, fire, and water. A 16-hit die elemental is summoned from the appropriate elemental plane." },
  { id: "mu-5-contact-other-plane", name: "Contact Other Plane", level: 5, class: "Magic User", range: "0", duration: "Special", areaOfEffect: "Personal", components: "V", castingTime: "1 turn", savingThrow: "None", phbPage: 88, description: "When this spell is cast, the magic-user sends his or her mind to another plane of existence in order to receive advice and information from powers there." },
  { id: "mu-5-dismissal", name: "Dismissal", level: 5, class: "Magic User", range: "1\"", duration: "Permanent", areaOfEffect: "One creature", components: "V, S, M", castingTime: "1 round", savingThrow: "Neg.", phbPage: 89, description: "By means of this spell, the magic-user seeks to force or allow some creature from another plane of existence to return to its proper plane. The spell is most effective against extraplanar creatures." },
  { id: "mu-5-distance-distortion", name: "Distance Distortion", level: 5, class: "Magic User", range: "1\"/level", duration: "2 turns/level", areaOfEffect: "100 sq. ft./level", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 89, description: "This spell is used in conjunction with earth elemental magic to make an area seem larger or smaller than it actually is. Outdoor use of this spell is also possible." },
  { id: "mu-5-extension-2", name: "Extension II", level: 5, class: "Magic User", range: "0", duration: "Special", areaOfEffect: "Special", components: "V", castingTime: "3", savingThrow: "None", phbPage: 89, description: "This spell is the same as the fourth level extension I spell, except that it will extend first through fourth level spells, and its effect is to add 50% to the spell duration." },
  { id: "mu-5-feeblemind", name: "Feeblemind", level: 5, class: "Magic User", range: "1\"/level", duration: "Permanent", areaOfEffect: "One creature", components: "V, S, M", castingTime: "5", savingThrow: "Neg.", phbPage: 89, description: "This spell is used solely against people or creatures who use magic spells. The feeblemind causes the target's intellect to collapse, rendering the subject incapable of casting spells." },
  { id: "mu-5-hold-monster", name: "Hold Monster", level: 5, class: "Magic User", range: "6\"", duration: "1 round/level", areaOfEffect: "One to four creatures", components: "V, S, M", castingTime: "5", savingThrow: "Neg.", phbPage: 89, description: "This spell will immobilize and hold helpless 1-4 creatures (the caster's choice) for the spell's duration. The material component is one hard metal bar or rod for each monster to be held." },
  { id: "mu-5-leomund's-secret-chest", name: "Leomund's Secret Chest", level: 5, class: "Magic User", range: "Special", duration: "60 days", areaOfEffect: "One chest, about 2 x 2 x 3 feet", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 90, description: "This spell enables the magic-user to hide a chest on the Ethereal Plane for up to 60 days, being able to recall it when desired." },
  { id: "mu-5-magic-jar", name: "Magic Jar", level: 5, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "One creature", components: "V, S, M", castingTime: "1 round", savingThrow: "Special", phbPage: 90, description: "By casting a magic jar spell, the magic-user is able to transfer his or her life force into a special receptacle (a gem or large crystal). From there the magic-user can attempt to possess the body of another creature." },
  { id: "mu-5-monster-summoning-3", name: "Monster Summoning III", level: 5, class: "Magic User", range: "4\"", duration: "4 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 90, description: "This spell summons 1d4 third level monsters. These appear within the spell's range and attack the magic-user's opponents." },
  { id: "mu-5-passwall", name: "Passwall", level: 5, class: "Magic User", range: "3\"", duration: "3 turns + 1 turn/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 91, description: "A passwall spell enables the spell caster to open a passage through wooden, plaster, or stone walls, but not through metal or other harder materials. The opening is 10 feet wide, 10 feet tall, and 10 feet deep. Material component is a pinch of sesame seeds." },
  { id: "mu-5-stone-shape", name: "Stone Shape", level: 5, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "3 cu. ft. + 1 cu. ft./level", components: "V, S, M", castingTime: "1 round", savingThrow: "None", phbPage: 91, description: "By means of this spell, the magic-user can form an existing piece of stone into any shape that suits his or her purposes. For example, a stone wall could be shaped into an archway." },
  { id: "mu-5-telekinesis", name: "Telekinesis", level: 5, class: "Magic User", range: "1\"/level", duration: "2 rounds + 1 round/level", areaOfEffect: "25 lbs./level", components: "V, S", castingTime: "5", savingThrow: "None", phbPage: 91, description: "By means of this spell, the magic-user is able to move objects by concentration alone. The weight of objects which can be moved is 25 lbs. per level of experience of the magic-user." },
  { id: "mu-5-teleport", name: "Teleport", level: 5, class: "Magic User", range: "Touch", duration: "Instantaneous", areaOfEffect: "Special", components: "V", castingTime: "2", savingThrow: "None", phbPage: 91, description: "By means of this spell, the magic-user instantly transfers himself or herself, or any single creature designated, to a well known or familiar locale. Success depends on how well the caster knows the destination." },
  { id: "mu-5-transmute-rock-to-mud", name: "Transmute Rock to Mud", level: 5, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "2\" x 2\" x 2\" volume", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 92, description: "This spell transmutes natural rock of any sort into an equal volume of mud. The mud remains for 1 week." },
  { id: "mu-5-wall-of-force", name: "Wall of Force", level: 5, class: "Magic User", range: "3\"", duration: "1 turn + 1 round/level", areaOfEffect: "20' x 10' plane or 6'+ radius hemisphere", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 92, description: "A wall of force creates an invisible, immobile barrier in the locale desired by the magic-user. The spell caster can create a wall of force up to 20 feet long by 10 feet wide, or he or she can create a globe of force." },
  { id: "mu-5-wall-of-iron", name: "Wall of Iron", level: 5, class: "Magic User", range: "5\"/level", duration: "Permanent", areaOfEffect: "15 sq. ft./level", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 92, description: "When this spell is cast, the magic-user causes a vertical iron wall to spring into being. This wall can be used to seal off a passage or close a breach, for the wall inserts itself into any surrounding nonliving material if its area is sufficient to do so." },
  { id: "mu-5-wall-of-stone", name: "Wall of Stone", level: 5, class: "Magic User", range: "5\"/level", duration: "Permanent", areaOfEffect: "Special", components: "V, S, M", castingTime: "5", savingThrow: "None", phbPage: 92, description: "This spell creates a wall of granite rock which merges into adjoining rock surfaces. It is 4 inches thick and up to 20 sq. ft. per level of experience of the spell caster." },
  { id: "mu-6-anti-magic-shell", name: "Anti-Magic Shell", level: 6, class: "Magic User", range: "0", duration: "1 turn/level", areaOfEffect: "1' radius/level sphere", components: "V, S", castingTime: "1", savingThrow: "None", phbPage: 93, description: "By casting this spell, the magic-user surrounds himself or herself with an invisible barrier which moves with the magic-user. This barrier totally negates any magic used inside the sphere, and all spells cast from outside the sphere which normally would affect creatures within the sphere." },
  { id: "mu-6-bigbys-forceful-hand", name: "Bigby's Forceful Hand", level: 6, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 93, description: "Bigby's forceful hand is a more powerful version of Bigby's interposing hand (see the fifth level spell), and the effects are identical save that the hand will move to push back a creature that the magic-user designates." },
  { id: "mu-6-chain-lightning", name: "Chain Lightning", level: 6, class: "Magic User", range: "4\"/level", duration: "Instantaneous", areaOfEffect: "Special", components: "V, S, M", castingTime: "5", savingThrow: "1/2", phbPage: 93, description: "When this spell is cast, the magic-user creates a bolt of electrical energy that arcs from one creature to another, striking the first target for the full damage, then the next for diminished damage, and so on." },
  { id: "mu-6-control-weather", name: "Control Weather", level: 6, class: "Magic User", range: "0", duration: "4d6 hours", areaOfEffect: "4d4 square miles", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 94, description: "The magic-user is able to alter weather in the local area. It takes 1 turn for the spell to take effect. The magic-user can call forth weather appropriate to the climate and season of the area." },
  { id: "mu-6-death-spell", name: "Death Spell", level: 6, class: "Magic User", range: "1\"/level", duration: "Instantaneous", areaOfEffect: "1/2\" x 1/2\" area", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 94, description: "When a death spell is cast, it snuffs out the life forces of creatures in the area of effect instantly and irrevocably. Creatures with 8 or more hit dice are unaffected. Between 1 and 4 creatures of 4-8 hit dice are affected, or between 1 and 6 creatures of 4 or fewer hit dice." },
  { id: "mu-6-disintegrate", name: "Disintegrate", level: 6, class: "Magic User", range: "1\"/level", duration: "Instantaneous", areaOfEffect: "Special", components: "V, S, M", castingTime: "6", savingThrow: "Neg.", phbPage: 94, description: "This spell causes matter to vanish — both living and non-living material. A single creature or object is the target of the spell. Only a single creature can be affected, unless the optional rule for a broad blast form of the spell is used." },
  { id: "mu-6-enchant-an-item", name: "Enchant an Item", level: 6, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "One item", components: "V, S, M", castingTime: "Special", savingThrow: "Special", phbPage: 94, description: "This spell is used for one purpose — to prepare an item for enchanting by further spells. The item must not be magical, and it must also be something the caster desires to enchant." },
  { id: "mu-6-extension-3", name: "Extension III", level: 6, class: "Magic User", range: "0", duration: "Special", areaOfEffect: "Special", components: "V", castingTime: "4", savingThrow: "None", phbPage: 95, description: "This spell is the same as the fourth level extension I spell, except that it extends the duration of first through fifth level spells by a full 100%, i.e., doubles it." },
  { id: "mu-6-geas", name: "Geas", level: 6, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "One creature", components: "V", castingTime: "4", savingThrow: "None", phbPage: 95, description: "A geas spell places a magical command on a creature (usually human or humanoid) to carry out some service or refrain from some action or course of activity, as desired by the spell caster." },
  { id: "mu-6-glassee", name: "Glassee", level: 6, class: "Magic User", range: "Touch", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 round", savingThrow: "None", phbPage: 95, description: "By means of this spell, the magic-user can cause a section of metal, stone, or wood to become transparent as glass, enabling the magic-user to see through it as if it were a window." },
  { id: "mu-6-globe-of-invulnerability", name: "Globe of Invulnerability", level: 6, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "5' radius sphere", components: "V, S, M", castingTime: "1", savingThrow: "None", phbPage: 95, description: "This spell is similar to the fourth level spell, minor globe of invulnerability, except that it prevents all spells through fourth level from affecting creatures within it." },
  { id: "mu-6-guards-and-wards", name: "Guards and Wards", level: 6, class: "Magic User", range: "0", duration: "6 turns/level", areaOfEffect: "Up to 400 sq. ft./level", components: "V, S, M", castingTime: "3 turns", savingThrow: "None", phbPage: 95, description: "This special spell is primarily used to defend the magic-user's stronghold. The ward protects a 200 square foot area for every level of the spell caster with multiple magical effects." },
  { id: "mu-6-invisible-stalker", name: "Invisible Stalker", level: 6, class: "Magic User", range: "1\"", duration: "Special", areaOfEffect: "Special", components: "V, S", castingTime: "1 round", savingThrow: "None", phbPage: 96, description: "This spell summons an invisible stalker from the elemental plane of Air. This creature follows the instructions of the magic-user who created it, serving as a spy or assassin." },
  { id: "mu-6-legend-lore", name: "Legend Lore", level: 6, class: "Magic User", range: "0", duration: "Special", areaOfEffect: "Special", components: "V, S, M", castingTime: "Special", savingThrow: "None", phbPage: 96, description: "The legend lore spell is used to determine legendary information regarding a known person, place, or thing. If the person or item is present, or the place is at hand, the casting time is only 1d4+1 turns." },
  { id: "mu-6-lower-water", name: "Lower Water", level: 6, class: "Magic User", range: "8\"", duration: "5 rounds/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 96, description: "This spell causes water or similar liquid to reduce its depth by as much as 50% for the spell's duration. The water is lowered within a 4\" x 4\" area." },
  { id: "mu-6-monster-summoning-4", name: "Monster Summoning IV", level: 6, class: "Magic User", range: "5\"", duration: "5 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 96, description: "This spell summons 1d3 fourth level monsters. These appear within the spell's range and attack the magic-user's opponents." },
  { id: "mu-6-move-earth", name: "Move Earth", level: 6, class: "Magic User", range: "1\"/level", duration: "Permanent", areaOfEffect: "Special", components: "V, S, M", castingTime: "Special", savingThrow: "None", phbPage: 96, description: "When cast, the move earth spell moves masses of earth (clay, loam, sand) in the area of effect at a rate of 6\" per turn. Thus, hills can be leveled, cliffs created, valleys dug, etc." },
  { id: "mu-6-otiluke's-freezing-sphere", name: "Otiluke's Freezing Sphere", level: 6, class: "Magic User", range: "Special", duration: "Special", areaOfEffect: "Special", components: "V, S, M", castingTime: "6", savingThrow: "Special", phbPage: 96, description: "Otiluke's freezing sphere is a powerful multi-purpose spell of several distinct effects. The magic-user can create a globe of cold to hurl at enemies, a ray of cold, or a cold zone around the caster." },
  { id: "mu-6-part-water", name: "Part Water", level: 6, class: "Magic User", range: "1\"/level", duration: "5 rounds/level", areaOfEffect: "3\" wide x 1\" deep x 2\" long/level path", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 97, description: "By means of this spell, the magic-user is able to cause water or similar liquid to move apart, thus forming a trough. The depth and length of the trough created depends on the level of the magic-user." },
  { id: "mu-6-project-image", name: "Project Image", level: 6, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 97, description: "By means of this spell, the magic-user creates a nonmaterial duplicate of himself or herself projecting it to any location desired within the spell range. This image performs actions decided by the magic-user." },
  { id: "mu-6-reincarnation", name: "Reincarnation", level: 6, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "Person touched", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 97, description: "This spell allows the magic-user to reincarnate a dead creature (which has been deceased for no longer than 1 week) in another body. The new incarnation is random, and the magic-user has no control over what form is taken." },
  { id: "mu-6-repulsion", name: "Repulsion", level: 6, class: "Magic User", range: "0", duration: "1 round/2 levels", areaOfEffect: "1\" wide path, 1\" long/level", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 97, description: "When this spell is cast, the magic-user is able to cause all creatures in the path of the area of effect to move away from the magic-user at maximum movement speed." },
  { id: "mu-6-stone-to-flesh", name: "Stone to Flesh", level: 6, class: "Magic User", range: "1\"/level", duration: "Permanent", areaOfEffect: "One creature", components: "V, S, M", castingTime: "6", savingThrow: "Special", phbPage: 97, description: "The stone to flesh spell turns any petrified creature back to its original state without harm to the creature. The reverse, flesh to stone, turns any creature into a statue." },
  { id: "mu-6-tenser's-transformation", name: "Tenser's Transformation", level: 6, class: "Magic User", range: "0", duration: "1 round/level", areaOfEffect: "Personal", components: "V, S, M", castingTime: "6", savingThrow: "None", phbPage: 98, description: "When Tenser's transformation is cast, the magic-user becomes a berserk fighter of the greatest power. The caster fights as a fighter of equal level, gaining added hit points, better armor class, and a rage-driven combat bonus." },
  { id: "mu-7-bigby's-grasping-hand", name: "Bigby's Grasping Hand", level: 7, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 98, description: "This spell creates a large magical hand which appears and grasps the opponent designated by the caster." },
  { id: "mu-7-cacodemon", name: "Cacodemon", level: 7, class: "Magic User", range: "1\"", duration: "Special", areaOfEffect: "Special", components: "V, S, M", castingTime: "1 hour", savingThrow: "None", phbPage: 98, description: "This spell summons a demon from the lower planes. The magic-user must inscribe protective magic circles and pentagrams before attempting the summoning." },
  { id: "mu-7-delayed-blast-fireball", name: "Delayed Blast Fireball", level: 7, class: "Magic User", range: "10\" + 1\"/level", duration: "Special", areaOfEffect: "2\" radius sphere", components: "V, S, M", castingTime: "7", savingThrow: "1/2", phbPage: 98, description: "This spell creates a fireball that can be set to go off at a trigger, a timed delay, or on impact. The damage is 1d6+1 per level of the caster." },
  { id: "mu-7-drawmij's-instant-summons", name: "Drawmij's Instant Summons", level: 7, class: "Magic User", range: "Infinite", duration: "Instantaneous", areaOfEffect: "One small object", components: "V, S, M", castingTime: "1 segment", savingThrow: "None", phbPage: 99, description: "When this spell is cast, the magic-user teleports a specially prepared small object directly to his or her hand." },
  { id: "mu-7-duo-dimension", name: "Duo-Dimension", level: 7, class: "Magic User", range: "0", duration: "3 rounds + 1 round/level", areaOfEffect: "Personal", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 99, description: "When this spell is cast, the magic-user becomes two-dimensional. He or she exists in only two dimensions, becoming invisible from certain angles." },
  { id: "mu-7-leomund's-magnificent-mansion", name: "Leomund's Magnificent Mansion", level: 7, class: "Magic User", range: "1\"", duration: "1 hour + 1 hour/level", areaOfEffect: "300 sq. ft./level", components: "V, S, M", castingTime: "7 rounds", savingThrow: "None", phbPage: 99, description: "By means of this spell, the magic-user conjures up an extradimensional dwelling, entrance to which can be gained only at a single point." },
  { id: "mu-7-limited-wish", name: "Limited Wish", level: 7, class: "Magic User", range: "Unlimited", duration: "Special", areaOfEffect: "Special", components: "V", castingTime: "Special", savingThrow: "Special", phbPage: 100, description: "A limited wish is a very powerful but difficult spell. It will alter reality in a limited manner." },
  { id: "mu-7-mass-invisibility", name: "Mass Invisibility", level: 7, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "60\" x 60\" area", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 100, description: "This spell makes all creatures in the area invisible. This is a more powerful version of the invisible spell that affects an entire group." },
  { id: "mu-7-monster-summoning-5", name: "Monster Summoning V", level: 7, class: "Magic User", range: "6\"", duration: "6 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 100, description: "This spell summons 1d3 fifth level monsters. These appear within the spell's range and attack the magic-user's opponents." },
  { id: "mu-7-mordenkainen's-sword", name: "Mordenkainen's Sword", level: 7, class: "Magic User", range: "3\"", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 100, description: "Upon casting this spell, the magic-user brings into being a shimmering, sword-like plane of force. The magic sword attacks at an attack roll as a fighter of the same level." },
  { id: "mu-7-phase-door", name: "Phase Door", level: 7, class: "Magic User", range: "Touch", duration: "1 usage/2 levels", areaOfEffect: "Special", components: "V", castingTime: "7", savingThrow: "None", phbPage: 100, description: "When this spell is cast, the magic-user creates an ethereal passage through wooden or plaster walls, stone walls, and similar surfaces. Only the spell caster and those he or she designates may use the passage." },
  { id: "mu-7-power-word-stun", name: "Power Word, Stun", level: 7, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "One creature", components: "V", castingTime: "1", savingThrow: "None", phbPage: 100, description: "When a power word, stun is uttered, any creature the magic-user has targeted will be stunned for a variable amount of time depending on its hit points." },
  { id: "mu-7-reverse-gravity", name: "Reverse Gravity", level: 7, class: "Magic User", range: "2\"", duration: "1 second (1/10 of a round)", areaOfEffect: "30' x 30' area", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 101, description: "This spell reverses gravity in the area of effect, causing all unattached objects and creatures to fall upward at the same rate that they would normally fall down." },
  { id: "mu-7-sequester", name: "Sequester", level: 7, class: "Magic User", range: "Touch", duration: "1 week + 1 day/level", areaOfEffect: "2 cu. ft./level", components: "V, S, M", castingTime: "1 turn", savingThrow: "Special", phbPage: 101, description: "When cast, this spell prevents detection and location spells from locating an object, creature, or magical location until the spell's duration expires." },
  { id: "mu-7-simulacrum", name: "Simulacrum", level: 7, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "One creature", components: "V, S, M", castingTime: "Special", savingThrow: "None", phbPage: 101, description: "By means of this spell, the magic-user creates a duplicate of any creature. The simulacrum appears to be the same as the original creature, but it is only 51-60% as powerful." },
  { id: "mu-7-spell-turning", name: "Spell Turning", level: 7, class: "Magic User", range: "0", duration: "Until expended or until 3 rounds/level", areaOfEffect: "Personal", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 102, description: "This spell causes spells cast at the magic-user to rebound upon the original caster." },
  { id: "mu-7-statue", name: "Statue", level: 7, class: "Magic User", range: "Touch", duration: "1 hour/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "7", savingThrow: "None", phbPage: 102, description: "When a statue spell is cast, the magic-user or other creature is allowed to alter his or her form and substance to that of a statue." },
  { id: "mu-7-teleport-without-error", name: "Teleport Without Error", level: 7, class: "Magic User", range: "Touch", duration: "Instantaneous", areaOfEffect: "Special", components: "V", castingTime: "2", savingThrow: "None", phbPage: 102, description: "This spell is the same as the fifth level spell teleport, except that the magic-user is able to teleport without error to any place he or she has been, up to 1,000 miles away per level." },
  { id: "mu-7-torment", name: "Torment", level: 7, class: "Magic User", range: "1\"", duration: "Special", areaOfEffect: "One creature from another plane", components: "V, S, M", castingTime: "1 round", savingThrow: "None", phbPage: 102, description: "This spell is used to force a creature from another plane to do the will of the magic-user through threats of torture." },
  { id: "mu-7-vanish", name: "Vanish", level: 7, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "One object, up to 100 lbs./level", components: "V", castingTime: "2", savingThrow: "None", phbPage: 102, description: "When the magic-user employs this spell, he or she causes an object to vanish — teleporting to a place the magic-user knows." },
  { id: "mu-8-antipathy-sympathy", name: "Antipathy/Sympathy", level: 8, class: "Magic User", range: "3\"", duration: "2 hours/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "6 turns", savingThrow: "Special", phbPage: 103, description: "This spell allows the magic-user to set certain preferences toward objects, areas, or creatures for other creatures. Antipathy causes creatures to avoid an object or area; sympathy causes creatures to be attracted to it." },
  { id: "mu-8-bigby's-clenched-fist", name: "Bigby's Clenched Fist", level: 8, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "8", savingThrow: "None", phbPage: 103, description: "This spell is a more powerful version of Bigby's forceful hand. The clenched fist strikes its target each round, doing 1d6 damage and potentially staggering it." },
  { id: "mu-8-clone", name: "Clone", level: 8, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "One cloned creature", components: "V, S, M", castingTime: "1 turn", savingThrow: "None", phbPage: 104, description: "This spell creates a duplicate of the creature from a small portion of its body (a hair, nail, piece of skin, etc.). The clone grows rapidly and is the image of the original." },
  { id: "mu-8-demand", name: "Demand", level: 8, class: "Magic User", range: "Unlimited", duration: "Special", areaOfEffect: "One creature", components: "V, S, M", castingTime: "Special", savingThrow: "Neg.", phbPage: 104, description: "This spell functions as the sixth level geas spell, but on any creature and over unlimited range. Non-compliance causes the creature to suffer ill health." },
  { id: "mu-8-glassteel", name: "Glassteel", level: 8, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "Object touched", components: "V, S, M", castingTime: "8", savingThrow: "None", phbPage: 105, description: "The glassteel spell turns crystal or glass into a transparent substance with the tensile strength and unbreakability of steel." },
  { id: "mu-8-incendiary-cloud", name: "Incendiary Cloud", level: 8, class: "Magic User", range: "3\"", duration: "4 rounds + 1d6 rounds", areaOfEffect: "Cylinder, 2\" radius, 2\" high", components: "V, S, M", castingTime: "2", savingThrow: "1/2", phbPage: 105, description: "An incendiary cloud spell creates a cloud of roiling, flaming vapors. The cloud does 2d6 points of damage per round, which may then intensify." },
  { id: "mu-8-mass-charm", name: "Mass Charm", level: 8, class: "Magic User", range: "1\"/level", duration: "Special", areaOfEffect: "Special", components: "V", castingTime: "8", savingThrow: "Neg.", phbPage: 105, description: "This spell affects a creature or creatures in the same manner as the first level charm person or the fourth level charm monster spell. It is different in that mass charm affects a number of creatures whose total level/hit dice does not exceed twice the level of the caster." },
  { id: "mu-8-maze", name: "Maze", level: 8, class: "Magic User", range: "5\"", duration: "Special", areaOfEffect: "One creature", components: "V, S", castingTime: "3", savingThrow: "None", phbPage: 105, description: "The maze spell sends the victim into a demi-dimensional space. The victim must find its way out of the maze to return to where it was. Humans find the exit 25% per minute; demi-humans 50% per minute; other creatures by Intelligence." },
  { id: "mu-8-mind-blank", name: "Mind Blank", level: 8, class: "Magic User", range: "3\"", duration: "1 day", areaOfEffect: "One creature", components: "V, S", castingTime: "8", savingThrow: "None", phbPage: 106, description: "When the mind blank spell is cast, the creature is totally protected from all devices and spells that detect, influence, or read emotions and thoughts. This includes all forms of ESP, charm, suggestion, and similar magic." },
  { id: "mu-8-monster-summoning-6", name: "Monster Summoning VI", level: 8, class: "Magic User", range: "7\"", duration: "7 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "8", savingThrow: "None", phbPage: 106, description: "This spell summons 1d3 sixth level monsters. These appear within the spell's range and attack the magic-user's opponents." },
  { id: "mu-8-otiluke's-telekinetic-sphere", name: "Otiluke's Telekinetic Sphere", level: 8, class: "Magic User", range: "2\"", duration: "2 rounds/level", areaOfEffect: "1' diameter/level sphere", components: "V, S, M", castingTime: "4", savingThrow: "Neg.", phbPage: 106, description: "This spell is similar to Otiluke's resilient sphere, but the telekinetic sphere both surrounds and moves any object within it." },
  { id: "mu-8-permanency", name: "Permanency", level: 8, class: "Magic User", range: "Special", duration: "Permanent", areaOfEffect: "Special", components: "V, S", castingTime: "2 rounds", savingThrow: "None", phbPage: 106, description: "This spell makes certain other spells permanent. The magic-user must sacrifice a point of Constitution when casting permanency. Only certain spells can be made permanent with this spell." },
  { id: "mu-8-polymorph-any-object", name: "Polymorph Any Object", level: 8, class: "Magic User", range: "5\"/level", duration: "Variable", areaOfEffect: "Special", components: "V, S, M", castingTime: "8", savingThrow: "Neg.", phbPage: 107, description: "This spell changes one object or creature into another. The duration is determined by the relative difference between what is polymorphed and what it is changed into." },
  { id: "mu-8-power-word-blind", name: "Power Word, Blind", level: 8, class: "Magic User", range: "5\"/level", duration: "Special", areaOfEffect: "One or more creatures in a 1\" radius", components: "V", castingTime: "1", savingThrow: "None", phbPage: 107, description: "When a power word, blind is spoken, one or more creatures within the area of effect and range of the spell are blinded. The duration of the blindness depends upon the total hit points of the creature(s) affected." },
  { id: "mu-8-serten's-spell-immunity", name: "Serten's Spell Immunity", level: 8, class: "Magic User", range: "Touch", duration: "1 turn/level", areaOfEffect: "Creature touched", components: "V, S, M", castingTime: "1 round/recipient", savingThrow: "None", phbPage: 107, description: "By use of this spell, the magic-user is able to confer upon one creature at a time a complete immunity to a specific spell or a whole school of spells for the spell duration." },
  { id: "mu-8-symbol", name: "Symbol", level: 8, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "Special", components: "V, S, M", castingTime: "8", savingThrow: "Special", phbPage: 108, description: "The symbol spell allows the magic-user to scribe a potent rune of power upon any surface. When triggered by a creature, the symbol delivers its effect. There are eight types: death, discord, fear, hopelessness, insanity, pain, sleep, and stunning." },
  { id: "mu-8-trap-the-soul", name: "Trap the Soul", level: 8, class: "Magic User", range: "1\"", duration: "Permanent until released", areaOfEffect: "One creature", components: "V, S, M", castingTime: "Special", savingThrow: "Neg.", phbPage: 108, description: "This spell forces a creature's life force (and its material body) into a special gem or jewel. The trap is either triggered by utterance of the creature's name or placed into an object the creature is likely to pick up." },
  { id: "mu-9-astral-spell", name: "Astral Spell", level: 9, class: "Magic User", range: "Touch", duration: "Special", areaOfEffect: "Special", components: "V, S", castingTime: "9", savingThrow: "None", phbPage: 108, description: "By means of the astral spell, the magic-user is able to project his or her astral body into the Astral Plane. The magic-user's astral body is connected to the physical body by a silver cord." },
  { id: "mu-9-bigby's-crushing-hand", name: "Bigby's Crushing Hand", level: 9, class: "Magic User", range: "1\"/level", duration: "1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "9", savingThrow: "None", phbPage: 109, description: "This spell is the culmination of the Bigby's hand series. The crushing hand can move, push, and crush creatures and objects. It does from 1d10 to 4d10 damage per round depending on how the magic-user directs it." },
  { id: "mu-9-gate", name: "Gate", level: 9, class: "Magic User", range: "3\"", duration: "Special", areaOfEffect: "Special", components: "V, S", castingTime: "9", savingThrow: "None", phbPage: 109, description: "The gate spell allows the magic-user to open a portal to another plane and call a specific creature from that plane to come to the caster's aid." },
  { id: "mu-9-imprisonment", name: "Imprisonment", level: 9, class: "Magic User", range: "Touch", duration: "Permanent", areaOfEffect: "One creature", components: "V, S", castingTime: "9", savingThrow: "Neg.", phbPage: 109, description: "When the magic-user casts an imprisonment spell and touches a creature, the victim is entombed in a state of suspended animation deep in the earth." },
  { id: "mu-9-meteor-swarm", name: "Meteor Swarm", level: 9, class: "Magic User", range: "4\"/level", duration: "Instantaneous", areaOfEffect: "Special", components: "V, S", castingTime: "9", savingThrow: "1/2", phbPage: 109, description: "A meteor swarm is a very powerful and spectacular spell which is similar to a fireball in many respects. When it is cast, either four spheres of 2 foot diameter or eight spheres of 1 foot diameter spring from the outstretched hand of the magic-user and streak outward." },
  { id: "mu-9-monster-summoning-7", name: "Monster Summoning VII", level: 9, class: "Magic User", range: "8\"", duration: "8 rounds + 1 round/level", areaOfEffect: "Special", components: "V, S, M", castingTime: "9", savingThrow: "None", phbPage: 110, description: "This spell summons 1d3 seventh level monsters or 1 eighth level monster. These appear within the spell's range and attack the magic-user's opponents." },
  { id: "mu-9-mordenkainen's-disjunction", name: "Mordenkainen's Disjunction", level: 9, class: "Magic User", range: "0", duration: "Instantaneous", areaOfEffect: "30' radius", components: "V", castingTime: "9", savingThrow: "Special", phbPage: 110, description: "When this spell is cast, all magic and magical items within the radius of the spell, except for those belonging to the caster, are disjoined. Spells are negated, and each magical item must make a saving throw." },
  { id: "mu-9-power-word-kill", name: "Power Word, Kill", level: 9, class: "Magic User", range: "1\"/level", duration: "Permanent", areaOfEffect: "Up to 120 hit points in a 1\" radius", components: "V", castingTime: "1", savingThrow: "None", phbPage: 110, description: "When a power word, kill is uttered, one or more creatures of any type within the spell range and area of effect are slain. The spell kills one creature with up to 60 hit points, or kills multiple creatures whose hit points total 120 or less." },
  { id: "mu-9-prismatic-sphere", name: "Prismatic Sphere", level: 9, class: "Magic User", range: "0", duration: "1 turn/level", areaOfEffect: "5' radius sphere around caster", components: "V", castingTime: "7", savingThrow: "Special", phbPage: 110, description: "This spell is similar to a prismatic wall, but surrounds the caster on all sides. The sphere consists of seven concentric, inter-locking bands of energy and is proof against most spells and all mundane attacks." },
  { id: "mu-9-shape-change", name: "Shape Change", level: 9, class: "Magic User", range: "0", duration: "1 turn/level", areaOfEffect: "Personal", components: "V, S, M", castingTime: "9", savingThrow: "None", phbPage: 111, description: "With this spell, the magic-user is able to assume the form of any creature, and gain its special abilities and immunities. The spell caster can change shape any number of times during the spell's duration." },
  { id: "mu-9-temporal-stasis", name: "Temporal Stasis", level: 9, class: "Magic User", range: "1\"", duration: "Permanent", areaOfEffect: "One creature", components: "V, S, M", castingTime: "9", savingThrow: "None", phbPage: 111, description: "Upon casting this spell, the magic-user places the recipient creature in a state of suspended animation. The creature does not age, does not need sustenance, and cannot be harmed by normal means." },
  { id: "mu-9-time-stop", name: "Time Stop", level: 9, class: "Magic User", range: "0", duration: "1d4+1 rounds", areaOfEffect: "15' radius", components: "V", castingTime: "9", savingThrow: "None", phbPage: 111, description: "Upon casting a time stop spell, the magic-user causes the flow of time to stop for 1d4+1 rounds in the area of effect. The magic-user may then act normally for the period while everything else is frozen in time." },
  { id: "mu-9-wish", name: "Wish", level: 9, class: "Magic User", range: "Unlimited", duration: "Special", areaOfEffect: "Special", components: "V", castingTime: "Special", savingThrow: "Special", phbPage: 112, description: "The wish spell is the most powerful magic known to mortal spellcasters. It can alter reality in significant ways, and it is limited only by the caster's ability to phrase the wish carefully and the DM's interpretation." },
];